CREATE OR REPLACE FUNCTION order_status_transition_guard() RETURNS trigger AS $$
BEGIN
  -- The @stateMachine of Order.status (D118): an update that leaves the
  -- column's value is no move, and any other must be one the machine lists.
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;
  IF OLD.status IN ('shipped') THEN
    RAISE EXCEPTION 'order.status is terminal at %: it cannot move to %', OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF (OLD.status IS NULL AND NEW.status IN ('placed'))
    OR (OLD.status = 'placed' AND NEW.status IN ('shipped'))
  THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'order.status cannot move from % to %', OLD.status, NEW.status
    USING ERRCODE = 'check_violation';
END;
$$ LANGUAGE plpgsql
